package com.bank.sequencer;

import java.util.Arrays;
import java.util.logging.*;

public class CyclicSortDemo {
    private static final Logger log = Logger.getLogger(CyclicSortDemo.class.getName());

    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        root.getHandlers()[0].setFormatter(new BankLogFormatter());
    }

    public static void main(String[] args) {
        // Shuffled settlement sequence numbers for the day's batch (a permutation of 1..5).
        int[] batch = {3, 1, 5, 4, 2};
        log.info(() -> "Incoming settlement batch: " + Arrays.toString(batch));

        SettlementSequencer sequencer = new SettlementSequencer();
        sequencer.cyclicSort(batch);

        log.info(() -> "Sorted settlement batch:  " + Arrays.toString(batch));
    }
}

