package com.bank.sequencer;

import java.util.logging.Logger;

public class SettlementSequencer {
    private static final Logger log = Logger.getLogger(SettlementSequencer.class.getName());

    // Sorts an array that is a permutation of 1..n in O(n) time, O(1) space.
    public void cyclicSort(int[] seq) {
        int i = 0;
        while (i < seq.length) {
            int correctIndex = seq[i] - 1;          // value v belongs at index v-1
            if (seq[i] != seq[correctIndex]) {       // not yet home — swap it there
                swap(seq, i, correctIndex);
            } else {
                i++;                                  // already home — move on
            }
        }
        log.fine("cyclicSort completed in a single linear pass");
    }

    private void swap(int[] a, int x, int y) {
        int tmp = a[x];
        a[x] = a[y];
        a[y] = tmp;
    }
}
